  enabled: true
  address: 10.9.0.1/24
  listen_port: 51820
  peers: [{name: phone, public_key: "xTIBA5rboUvnH4htodjb6e697QjLERt1NAB4mZqp8Dg=", address: 10.9.0.2}]
